"use strict";BX.namespace("BX.ShInSync");BX.ShInSync.UIAnchorsController=function(){this.isDebug=false;this.initialized=false;this.sliders={csvFile:{condition:new RegExp("/page/shinsync/csvfile[a-z0-9]+/","i"),options:{width:500,allowChangeHistory:true,allowChangeTitle:true,cacheable:false,label:{color:"#FFFFFF",bgColor:"#F1416C",opacity:80}},stopParameters:[]},xmlFile:{condition:new RegExp("/page/shinsync/xmlfile[a-z0-9]+/","i"),options:{width:500,allowChangeHistory:true,allowChangeTitle:true,cacheable:false,label:{color:"#FFFFFF",bgColor:"#F1416C",opacity:80}},stopParameters:[]}}};BX.ShInSync.UIAnchorsController.prototype={initialize:function(){if(this.initialized){return}if(!(BX.SidePanel&&BX.SidePanel.Instance)){return}if(window===window.top){this.bind()}this.initialized=true;this._log("init",true)},bind:function(){let rules=[];for(let key in this.sliders){if(!this.sliders.hasOwnProperty(key)){continue}let slider=this.sliders[key];let options=BX.prop.getObject(slider,"options",{});let loader=BX.prop.getString(slider,"loader","");if(!options.hasOwnProperty("cacheable")){options["cacheable"]=false}rules.push({condition:[slider.condition],stopParameters:BX.prop.getArray(slider,"stopParameters",[]),loader:loader,options:options})}BX.SidePanel.Instance.bindAnchors({rules:rules})},_log:function(value,allTime=false){if(this.isDebug||allTime){console.log(">> BX.ShInSync >>> UIAnchorsController >>",value)}}};BX.ShInSync.UIAnchorsController.init=function(){if(!!!BX.ShInSync.UIAnchors){BX.ShInSync.UIAnchors=new BX.ShInSync.UIAnchorsController;BX.ShInSync.UIAnchors.initialize()}};